import{c as l,Z as o,Q as r,j as n,m as s,o as i}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"破阵子·为陈同甫赋壮词以寄之","description":"","frontmatter":{"title":"破阵子·为陈同甫赋壮词以寄之","author":"辛弃疾","dynasty":"宋"},"headers":[],"relativePath":"books/shici/songci/9.md","filePath":"books/shici/songci/9.md"}'),h={name:"books/shici/songci/9.md"};function c(u,a,p,d,_,m){const t=o("PoemAuthor"),e=o("PoemNav");return r(),n("div",null,[a[0]||(a[0]=s('<h1 id="破阵子·为陈同甫赋壮词以寄之" tabindex="-1">破阵子·为陈同甫赋壮词以寄之 <a class="header-anchor" href="#破阵子·为陈同甫赋壮词以寄之" aria-label="Permalink to &quot;破阵子·为陈同甫赋壮词以寄之&quot;">​</a></h1><p><strong>[宋] <a href="/authors/xinqiji.html">辛弃疾</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>醉里挑灯看剑，梦回吹角连营。八百里分麾下炙，五十弦翻塞外声，沙场秋点兵。</p><p>马作的卢飞快，弓如霹雳弦惊。了却君王天下事，赢得生前身后名。可怜白发生！</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>破阵子：词牌名</li><li>陈同甫：陈亮，字同甫，南宋思想家、文学家，辛弃疾的好友</li><li>挑灯：拨亮灯火</li><li>吹角连营：各个军营接连吹起号角</li><li>八百里：指牛，典出《世说新语》</li><li>麾下：部下</li><li>炙：烤肉</li><li>五十弦：指瑟，这里泛指乐器</li><li>翻：演奏</li><li>塞外声：边塞的军乐</li><li>点兵：检阅军队</li><li>的卢：一种快马，传说刘备骑的卢马跃过檀溪</li><li>霹雳：雷声，形容弓弦响声如雷</li><li>了却：完成</li><li>天下事：指收复失地、统一国家的大业</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>醉酒后拨亮灯火细看宝剑，梦中回到了号角连营的战场。把烤牛肉分给部下，乐器演奏着边塞的军歌，秋天在战场上检阅军队。</p><p>战马像的卢一样飞快，弓弦像霹雳一样震响。完成了君王收复天下的大业，赢得了生前和死后的美名。可惜如今已经白发丛生！</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首词是辛弃疾寄给好友陈亮的壮词，通过回忆当年的军旅生活，表达了词人壮志难酬的悲愤之情。</p><p>上片写梦境中的军旅生活。&quot;醉里挑灯看剑&quot;，开篇就展现了一个壮志未酬的英雄形象。&quot;梦回吹角连营&quot;，写词人梦中回到了当年的军营。&quot;八百里分麾下炙，五十弦翻塞外声，沙场秋点兵&quot;，描绘了壮丽的军营生活场景，将士们分食烤肉，军乐激昂，秋天检阅军队，气势磅礴。</p><p>下片写战斗场面和壮志难酬的悲愤。&quot;马作的卢飞快，弓如霹雳弦惊&quot;，以夸张的手法写战斗的激烈。&quot;了却君王天下事，赢得生前身后名&quot;，写词人当年的雄心壮志。然而结尾&quot;可怜白发生&quot;一句，突然转折，将前面的豪情壮志全部打破，表达了词人壮志未酬、年华老去的悲愤。</p><p>全词气势磅礴，豪情万丈，结尾却陡然跌落，形成强烈的对比，将词人的爱国热情和壮志难酬的悲愤表现得淋漓尽致。</p>',15)),i(t,{name:"辛弃疾",years:"1140年－1207年",desc:"字幼安，号稼轩，南宋豪放派词人代表，与苏轼并称“苏辛”。其词风格多样，既有豪放激昂之作，也有婉约细腻之篇。",link:"/authors/xinqiji"}),i(e)])}const b=l(h,[["render",c]]);export{f as __pageData,b as default};
